import{a as e,i as t,r as n,t as r}from"./app-BKUFyoHP.js";var i=JSON.parse(`{"path":"/skills.html","title":"Technical Skills","lang":"en-US","frontmatter":{},"git":{"updatedTime":1786469929000,"contributors":[{"name":"ashwani","username":"ashwani","email":"ashwanipandey679@gmail.com","commits":1,"url":"https://github.com/ashwani"}],"changelog":[{"hash":"2590e3637c6d21e6a31f107b35c17814726bfb8b","time":1786469929000,"email":"ashwanipandey679@gmail.com","author":"ashwani","message":"Added code."}]},"filePathRelative":"skills.md"}`),a={name:`skills.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="technical-skills" tabindex="-1"><a class="header-anchor" href="#technical-skills"><span>Technical Skills</span></a></h1><p>A comprehensive overview of my programming languages, frameworks, developer tools, database systems, and methodologies.</p><hr><h2 id="languages-core-frameworks" tabindex="-1"><a class="header-anchor" href="#languages-core-frameworks"><span>Languages &amp; Core Frameworks</span></a></h2><table><thead><tr><th style="text-align:left;">Category</th><th style="text-align:left;">Skills &amp; Frameworks</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Backend Languages</strong></td><td style="text-align:left;">PHP (OOP), Java (Core &amp; Advanced), C++, JavaScript (ES6+), Node.js (Runtime)</td></tr><tr><td style="text-align:left;"><strong>PHP Ecosystem</strong></td><td style="text-align:left;">Laravel, Adobe Commerce / Magento 2 (Custom extension development)</td></tr><tr><td style="text-align:left;"><strong>Java Ecosystem</strong></td><td style="text-align:left;">Spring, Spring Boot, Spring Microservices</td></tr><tr><td style="text-align:left;"><strong>JavaScript Ecosystem</strong></td><td style="text-align:left;">Node.js (MERN Backend), Express.js</td></tr></tbody></table><hr><h2 id="frontend-ui-styling" tabindex="-1"><a class="header-anchor" href="#frontend-ui-styling"><span>Frontend &amp; UI Styling</span></a></h2><ul><li><strong>Frontend Frameworks &amp; Libraries</strong>: Vue.js, React.js (MERN Frontend)</li><li><strong>E-Commerce Styling</strong>: Hyvä Theme (Magento 2 Tailwind CSS framework)</li><li><strong>Web UI Standards</strong>: HTML5, CSS3, JavaScript</li><li><strong>CSS Frameworks</strong>: Tailwind CSS, Vanilla CSS</li></ul><hr><h2 id="database-management" tabindex="-1"><a class="header-anchor" href="#database-management"><span>Database Management</span></a></h2><ul><li><strong>Relational Databases</strong>: SQL, MySQL, MariaDB, PostgreSQL</li><li><strong>NoSQL Databases</strong>: MongoDB (MERN Stack Database)</li><li><strong>Optimization Techniques</strong>: Query optimization, indexing, schema design, batch insert/update optimizations</li></ul><hr><h2 id="web-api-architectures-services" tabindex="-1"><a class="header-anchor" href="#web-api-architectures-services"><span>Web API Architectures &amp; Services</span></a></h2><ul><li><strong>API Formats</strong>: GraphQL (Magento 2 GraphQL APIs, custom resolvers), RESTful Web Services</li><li><strong>Cloud &amp; Storage Services</strong>: Amazon Web Services (AWS S3 Integration)</li><li><strong>Payment Gateways</strong>: Stripe API Integration (subscriptions, payment methods, CRUD operations), CMI Payment Gateway</li></ul><hr><h2 id="testing-automation" tabindex="-1"><a class="header-anchor" href="#testing-automation"><span>Testing &amp; Automation</span></a></h2><ul><li><strong>Browser-based Testing</strong>: Playwright (end-to-end user-journey testing, custom test scripts for Magento marketplace modules)</li><li><strong>Unit Testing</strong>: Basic PHPUnit and JUnit verification</li></ul><hr><h2 id="system-design-background-jobs" tabindex="-1"><a class="header-anchor" href="#system-design-background-jobs"><span>System Design &amp; Background Jobs</span></a></h2><ul><li><strong>Asynchronous Jobs</strong>: Magento Cron Jobs, custom cron schedules, queue management, background process scheduling</li><li><strong>Message Queues</strong>: Basic understanding of queues for batch processing</li></ul><hr><h2 id="architecture-version-control" tabindex="-1"><a class="header-anchor" href="#architecture-version-control"><span>Architecture &amp; Version Control</span></a></h2><ul><li><strong>Design Patterns</strong>: MVC (Model-View-Controller), MVVM (Model-View-ViewModel), Dependency Injection</li><li><strong>Collaborative Tools</strong>: Git, GitHub, Bitbucket, Jira</li><li><strong>Other</strong>: AI-assisted technical documentation, REST client API tools (Postman, Insomnia)</li></ul>`,23)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};